1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioResult = {
13	  results: StepResult[];
14	};
15	
16	const BASE_PREMIUMS = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	} as const satisfies Record<string, number>;
24	
25	const INSURANCE_VALUES = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	} as const satisfies Record<keyof typeof BASE_PREMIUMS, number>;
33	
34	type InsurableItemType = keyof typeof BASE_PREMIUMS;
35	
36	type Item = {
37	  type: InsurableItemType;
38	  material?: string;
39	  enchantment?: number;
40	  cursed?: boolean;
41	};
42	
43	type QuoteStep = {
44	  op: "quote";
45	  items: Item[];
46	};
47	
48	type Damage = {
49	  itemType: string;
50	  amount: number;
51	};
52	
53	type Incident = {
54	  cause: string;
55	  damages: Damage[];
56	};
57	
58	type ClaimStep = {
59	  op: "claim";
60	  policy: number;
61	  incident: Incident;
62	};
63	
64	type Step = QuoteStep | ClaimStep;
65	
66	type Customer = {
67	  yearsWithMHPCO: number;
68	};
69	
70	type Scenario = {
71	  customer: Customer;
72	  steps: Step[];
73	};
74	
75	const PROCESSING_FEE = 5;
76	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
77	const CURSE_SURCHARGE_PERCENT = 50;
78	const HIGH_ENCHANTMENT_THRESHOLD = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
80	const LOYALTY_THRESHOLD_YEARS = 2;
81	const LOYALTY_DISCOUNT_PERCENT = 20;
82	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
83	
84	const percentOf = (amount: number, percent: number): number =>
85	  (amount * percent) / 100;
86	
87	// The MHPCO always rounds in its own favour: premiums (which the customer
88	// pays) round up, payouts (which it pays out) round down.
89	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
90	
91	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
92	
93	// Exactly this many components of the same type form a "building block",
94	// priced as a unit rather than per item.
95	const BUILDING_BLOCK_SIZE = 3;
96	const BUILDING_BLOCK_BASE_PREMIUM = 60;
97	
98	const sumOf = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// The MHPCO refuses to process a scenario it cannot price or pay out on. Every
102	// such refusal names the offending value, so they all take the same shape:
103	// yield the value when there is one, reject with an explanation when there
104	// is not.
105	const orRejected = <Value>(
106	  value: Value | undefined,
107	  reason: string,
108	): Value => {
109	  if (value === undefined) {
110	    throw new Error(reason);
111	  }
112	
113	  return value;
114	};
115	
116	// The MHPCO insures exactly the item types its price list names.
117	const insurableItemTypes = Object.keys(BASE_PREMIUMS) as InsurableItemType[];
118	
119	const isInsurableItemType = (type: string): type is InsurableItemType =>
120	  insurableItemTypes.includes(type as InsurableItemType);
121	
122	const alikeItemGroups = (items: Item[]): Item[][] =>
123	  insurableItemTypes
124	    .map((type) => items.filter((item) => item.type === type))
125	    .filter((alikeItems) => alikeItems.length > 0);
126	
127	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
128	  alikeItems.length === BUILDING_BLOCK_SIZE;
129	
130	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
131	  formsBuildingBlock(alikeItems)
132	    ? BUILDING_BLOCK_BASE_PREMIUM
133	    : sumOf(alikeItems.map(itemBasePremiumOf));
134	
135	const policyBasePremiumOf = (items: Item[]): number =>
136	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
137	
138	const isCursed = (item: Item): boolean => item.cursed === true;
139	
140	// An item without an enchantment counts as enchantment 0 everywhere.
141	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
142	
143	const isHighlyEnchanted = (item: Item): boolean =>
144	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
145	
146	// A modifier adjusts a base premium by a percentage of it, when it applies to
147	// the subject it is about (an item, a contract, ...). A surcharge has a
148	// positive percent, a discount a negative one, so they all combine by summing.
149	// Modifiers are cumulative: every applicable one applies.
150	type Modifier<Subject> = {
151	  appliesTo: (subject: Subject) => boolean;
152	  percent: number;
153	};
154	
155	const modifierTotalOf = <Subject>(
156	  modifiers: Modifier<Subject>[],
157	  subject: Subject,
158	  basePremium: number,
159	): number =>
160	  sumOf(
161	    modifiers
162	      .filter((modifier) => modifier.appliesTo(subject))
163	      .map((modifier) => percentOf(basePremium, modifier.percent)),
164	  );
165	
166	const ITEM_MODIFIERS: Modifier<Item>[] = [
167	  { appliesTo: isCursed, percent: CURSE_SURCHARGE_PERCENT },
168	  { appliesTo: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
169	];
170	
171	// Item-specific modifiers apply to the base premium of the affected item.
172	const itemModifierTotalOf = (item: Item): number =>
173	  modifierTotalOf(ITEM_MODIFIERS, item, itemBasePremiumOf(item));
174	
175	const isLongStanding = (customer: Customer): boolean =>
176	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
177	
178	// A contract is one quote within a scenario. A quote is a follow-up when the
179	// customer already holds a policy with the MHPCO at the time it is drawn up.
180	type Contract = {
181	  customer: Customer;
182	  heldPoliciesBefore: number;
183	};
184	
185	const isFollowUpContract = (contract: Contract): boolean =>
186	  contract.heldPoliciesBefore > 0;
187	
188	// Policy-wide modifiers apply to the policy base premium and are about the
189	// contract as a whole rather than any single item.
190	const alwaysApplies = (): boolean => true;
191	
192	const POLICY_MODIFIERS: Modifier<Contract>[] = [
193	  { appliesTo: alwaysApplies, percent: INITIAL_ASSESSMENT_SURCHARGE_PERCENT },
194	  {
195	    appliesTo: (contract) => isLongStanding(contract.customer),
196	    percent: -LOYALTY_DISCOUNT_PERCENT,
197	  },
198	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
199	];
200	
201	const policyModifierTotalOf = (
202	  contract: Contract,
203	  policyBasePremium: number,
204	): number => modifierTotalOf(POLICY_MODIFIERS, contract, policyBasePremium);
205	
206	const quote = (step: QuoteStep, contract: Contract): QuoteResult => {
207	  const policyBasePremium = policyBasePremiumOf(step.items);
208	  const itemModifiers = sumOf(step.items.map(itemModifierTotalOf));
209	  const policyModifiers = policyModifierTotalOf(contract, policyBasePremium);
210	
211	  return {
212	    premium: roundedUpInMHPCOsFavour(
213	      policyBasePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
214	    ),
215	  };
216	};
217	
218	const DEDUCTIBLE_PER_DAMAGE = 100;
219	const CAP_MULTIPLIER = 2;
220	const PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
221	const PARTIAL_REIMBURSEMENT_PERCENT = 50;
222	
223	const roundedDownInMHPCOsFavour = (payout: number): number =>
224	  Math.floor(payout);
225	
226	const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type];
227	
228	// A policy is created by a quote step and remembers how much of its cap the
229	// customer has already claimed.
230	type Policy = {
231	  items: Item[];
232	  remainingCap: number;
233	};
234	
235	const isReimbursedInPart = (item: Item): boolean =>
236	  enchantmentOf(item) >= PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
237	
238	// The reimbursement clauses decide how much of the damage is covered; the
239	// deductible is then withheld from that amount.
240	const reimbursementOf = (damage: Damage, item: Item): number =>
241	  isReimbursedInPart(item)
242	    ? percentOf(damage.amount, PARTIAL_REIMBURSEMENT_PERCENT)
243	    : damage.amount;
244	
245	// The MHPCO does not entertain damages that would pay it.
246	const assertDamageIsNotNegative = (damage: Damage): void => {
247	  if (damage.amount < 0) {
248	    throw new Error(`damage amount cannot be negative: ${damage.amount}`);
249	  }
250	};
251	
252	const damagePayoutOf = (damage: Damage, item: Item): number => {
253	  assertDamageIsNotNegative(damage);
254	
255	  return reimbursementOf(damage, item) - DEDUCTIBLE_PER_DAMAGE;
256	};
257	
258	// The insured item a damage entry is about. The MHPCO does not pay for what it
259	// did not insure, so a damage naming anything else is rejected outright.
260	const damagedItemIn = (policy: Policy, damage: Damage): Item =>
261	  orRejected(
262	    policy.items.find((item) => item.type === damage.itemType),
263	    `damaged item is not insured by this policy: ${damage.itemType}`,
264	  );
265	
266	const incidentPayoutOf = (incident: Incident, policy: Policy): number =>
267	  roundedDownInMHPCOsFavour(
268	    sumOf(
269	      incident.damages.map((damage) =>
270	        damagePayoutOf(damage, damagedItemIn(policy, damage)),
271	      ),
272	    ),
273	  );
274	
275	// The total payout per policy is capped, so a claim can only draw what the cap
276	// still holds.
277	const drawnFromCap = (desiredPayout: number, policy: Policy): number =>
278	  Math.min(desiredPayout, policy.remainingCap);
279	
280	// Claiming draws the payout from the policy's remaining cap, so it yields both
281	// the result and the policy as it stands afterwards, rather than mutating.
282	const claim = (
283	  step: ClaimStep,
284	  policy: Policy,
285	): { result: ClaimResult; policy: Policy } => {
286	  const payout = drawnFromCap(incidentPayoutOf(step.incident, policy), policy);
287	  const remainingCap = policy.remainingCap - payout;
288	
289	  return {
290	    result: { payout, remainingCap },
291	    policy: { ...policy, remainingCap },
292	  };
293	};
294	
295	const policyFor = (items: Item[]): Policy => ({
296	  items,
297	  remainingCap: CAP_MULTIPLIER * sumOf(items.map(insuranceValueOf)),
298	});
299	
300	// A scenario is processed step by step: each step produces a result and may
301	// leave behind policies the later steps claim against. Policies are keyed by
302	// the index of the quote step that created them, which is how claim steps
303	// refer to them.
304	type Office = {
305	  policies: Map<number, Policy>;
306	  results: StepResult[];
307	};
308	
309	const emptyOffice = (): Office => ({ policies: new Map(), results: [] });
310	
311	// The scenario arrives as untyped JSON, so the item types it names have to be
312	// checked against the MHPCO's price list before anything is priced.
313	const assertItemTypeIsInsurable = (item: Item): void => {
314	  if (!isInsurableItemType(item.type)) {
315	    throw new Error(`unknown item type: ${item.type}`);
316	  }
317	};
318	
319	// Every step yields its result plus the policy it wrote, under the key that
320	// later steps use to find it.
321	type StepOutcome = {
322	  result: StepResult;
323	  policyKey: number;
324	  policy: Policy;
325	};
326	
327	const withOutcomeRecorded = (office: Office, outcome: StepOutcome): Office => ({
328	  policies: new Map(office.policies).set(outcome.policyKey, outcome.policy),
329	  results: [...office.results, outcome.result],
330	});
331	
332	const outcomeOf = (
333	  office: Office,
334	  step: Step,
335	  stepIndex: number,
336	  customer: Customer,
337	): StepOutcome => {
338	  if (step.op === "quote") {
339	    step.items.forEach(assertItemTypeIsInsurable);
340	    // Claims re-file the policy they draw on under its existing key, so the
341	    // number of policies on file only ever grows on a quote.
342	    const contract = { customer, heldPoliciesBefore: office.policies.size };
343	
344	    return {
345	      result: quote(step, contract),
346	      policyKey: stepIndex,
347	      policy: policyFor(step.items),
348	    };
349	  }
350	
351	  const claimed = claim(step, office.policies.get(step.policy)!);
352	
353	  return {
354	    result: claimed.result,
355	    policyKey: step.policy,
356	    policy: claimed.policy,
357	  };
358	};
359	
360	export const runScenario = (scenario: Scenario): ScenarioResult => {
361	  const office = scenario.steps.reduce(
362	    (office, step, stepIndex) =>
363	      withOutcomeRecorded(
364	        office,
365	        outcomeOf(office, step, stepIndex, scenario.customer),
366	      ),
367	    emptyOffice(),
368	  );
369	
370	  return { results: office.results };
371	};
